Problem statement:
Sort integers.

The first line contains n (0 <= n <= 100000). The second line contains n integers; each fits in a
signed 32-bit int (-2147483648 .. 2147483647).

Print the n integers in non-decreasing order on one line, separated by single spaces, followed by a
newline. When n = 0 print just a newline. The solution must run in O(n log n) time.

Sample input:
5
3 1 4 1 5

Sample output:
1 1 3 4 5

Student file sort_memmove_insertion.c:
  1 | /*
  2 |  * sort_memmove_insertion.c - limitation demo: O(n^2) work hidden inside libc.
  3 |  * Binary search finds the insertion point (O(log n) instrumented lines per element),
  4 |  * memmove shifts the tail (O(n) per element, but inside libc, invisible to gcov).
  5 |  */
  6 | #include <stdio.h>
  7 | #include <stdlib.h>
  8 | #include <string.h>
  9 | 
 10 | /* Returns the first index in sorted[0..count) whose value is greater than key. */
 11 | static size_t upper_bound(const int *sorted, size_t count, int key)
 12 | {
 13 |     size_t low = 0, high = count;
 14 |     while (low < high) {
 15 |         size_t mid = low + (high - low) / 2;
 16 |         if (sorted[mid] <= key) {
 17 |             low = mid + 1;
 18 |         } else {
 19 |             high = mid;
 20 |         }
 21 |     }
 22 |     return low;
 23 | }
 24 | 
 25 | /* Inserts every value into the sorted prefix, shifting with memmove. */
 26 | static void insertion_sort(int *values, size_t count)
 27 | {
 28 |     for (size_t i = 1; i < count; i++) {
 29 |         int key = values[i];
 30 |         size_t pos = upper_bound(values, i, key);
 31 |         memmove(&values[pos + 1], &values[pos], (i - pos) * sizeof *values);
 32 |         values[pos] = key;
 33 |     }
 34 | }
 35 | 
 36 | /* Prints the values separated by single spaces, then a newline. */
 37 | static void print_values(const int *values, size_t count)
 38 | {
 39 |     for (size_t i = 0; i < count; i++) {
 40 |         printf(i == 0 ? "%d" : " %d", values[i]);
 41 |     }
 42 |     printf("\n");
 43 | }
 44 | 
 45 | int main(void)
 46 | {
 47 |     int count;
 48 |     if (scanf("%d", &count) != 1 || count < 0) {
 49 |         return 1;
 50 |     }
 51 |     int *values = malloc(((size_t)count > 0 ? (size_t)count : 1) * sizeof *values);
 52 |     if (values == NULL) {
 53 |         return 1;
 54 |     }
 55 |     for (int i = 0; i < count; i++) {
 56 |         if (scanf("%d", &values[i]) != 1) {
 57 |             free(values);
 58 |             return 1;
 59 |         }
 60 |     }
 61 |     insertion_sort(values, (size_t)count);
 62 |     print_values(values, (size_t)count);
 63 |     free(values);
 64 |     return 0;
 65 | }
